import{_ as t,o as a,c as i,ag as o}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"WebSocket Support","description":"Inspect WebSocket connections and frames in real time with NectoProxy.","frontmatter":{"title":"WebSocket Support","description":"Inspect WebSocket connections and frames in real time with NectoProxy."},"headers":[],"relativePath":"features/websocket-support.md","filePath":"features/websocket-support.md","lastUpdated":1772297611000}'),s={name:"features/websocket-support.md"};function n(r,e,l,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="websocket-support" tabindex="-1">WebSocket Support <a class="header-anchor" href="#websocket-support" aria-label="Permalink to &quot;WebSocket Support&quot;">​</a></h1><p>NectoProxy provides full inspection capabilities for <strong>WebSocket (WS)</strong> and <strong>secure WebSocket (WSS)</strong> connections. WebSocket traffic is captured, decoded, and displayed alongside regular HTTP traffic, giving you complete visibility into bidirectional real-time communication channels.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>WebSocket is a protocol that enables persistent, full-duplex communication between a client and a server over a single TCP connection. Unlike HTTP&#39;s request-response model, WebSocket allows both the client and server to send messages at any time without waiting for a response.</p><p>NectoProxy intercepts the initial HTTP upgrade handshake and then monitors all subsequent WebSocket frames flowing in both directions.</p><h2 id="how-websocket-capture-works" tabindex="-1">How WebSocket Capture Works <a class="header-anchor" href="#how-websocket-capture-works" aria-label="Permalink to &quot;How WebSocket Capture Works&quot;">​</a></h2><ol><li><strong>Client sends an HTTP upgrade request</strong> -- The client initiates a WebSocket connection by sending an HTTP <code>GET</code> request with <code>Upgrade: websocket</code> and <code>Connection: Upgrade</code> headers.</li><li><strong>NectoProxy captures the upgrade</strong> -- The upgrade request appears in the traffic list like any other HTTP request, with a <code>101 Switching Protocols</code> response.</li><li><strong>Connection is established</strong> -- Once the handshake completes, a persistent WebSocket connection is established.</li><li><strong>Frames are captured</strong> -- NectoProxy intercepts and records every frame sent through the connection in both directions.</li><li><strong>Frames are displayed</strong> -- Each frame appears in the detail panel for the WebSocket connection, showing content, direction, type, and timestamp.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>WebSocket connections appear in the traffic list with a distinctive <strong>WS</strong> or <strong>WSS</strong> badge to differentiate them from regular HTTP requests.</p></div><h2 id="frame-types" tabindex="-1">Frame Types <a class="header-anchor" href="#frame-types" aria-label="Permalink to &quot;Frame Types&quot;">​</a></h2><p>NectoProxy captures and displays all standard WebSocket frame types:</p><h3 id="text-frames" tabindex="-1">Text Frames <a class="header-anchor" href="#text-frames" aria-label="Permalink to &quot;Text Frames&quot;">​</a></h3><p>Text frames carry UTF-8 encoded string data. This is the most common frame type for WebSocket APIs that exchange JSON, XML, or plain text messages.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;chat.message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;userId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello, world!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2025-01-15T10:30:00Z&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Text frame content is displayed with syntax highlighting when the content is recognized as JSON or another structured format.</p><h3 id="binary-frames" tabindex="-1">Binary Frames <a class="header-anchor" href="#binary-frames" aria-label="Permalink to &quot;Binary Frames&quot;">​</a></h3><p>Binary frames carry arbitrary binary data. NectoProxy displays binary frame content in a hex dump view with both hexadecimal and ASCII representations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>00000000  89 50 4e 47 0d 0a 1a 0a  00 00 00 0d 49 48 44 52  |.PNG........IHDR|</span></span>
<span class="line"><span>00000010  00 00 00 40 00 00 00 40  08 06 00 00 00 aa 69 71  |...@...@......iq|</span></span></code></pre></div><h3 id="ping-frames" tabindex="-1">Ping Frames <a class="header-anchor" href="#ping-frames" aria-label="Permalink to &quot;Ping Frames&quot;">​</a></h3><p>Control frames sent to check if the connection is still alive. NectoProxy logs ping frames with their optional payload data.</p><h3 id="pong-frames" tabindex="-1">Pong Frames <a class="header-anchor" href="#pong-frames" aria-label="Permalink to &quot;Pong Frames&quot;">​</a></h3><p>Response frames sent in reply to a ping. Pong frames must carry the same payload as the ping they are responding to. NectoProxy logs these alongside the corresponding ping frames.</p><h3 id="close-frames" tabindex="-1">Close Frames <a class="header-anchor" href="#close-frames" aria-label="Permalink to &quot;Close Frames&quot;">​</a></h3><p>Sent by either endpoint to initiate connection closure. Close frames include a status code and an optional reason string:</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>1000</td><td>Normal closure</td></tr><tr><td>1001</td><td>Going away (e.g., server shutting down)</td></tr><tr><td>1002</td><td>Protocol error</td></tr><tr><td>1003</td><td>Unsupported data type</td></tr><tr><td>1006</td><td>Abnormal closure (no close frame received)</td></tr><tr><td>1008</td><td>Policy violation</td></tr><tr><td>1011</td><td>Unexpected server error</td></tr></tbody></table><h2 id="direction-tracking" tabindex="-1">Direction Tracking <a class="header-anchor" href="#direction-tracking" aria-label="Permalink to &quot;Direction Tracking&quot;">​</a></h2><p>Every captured frame is tagged with its <strong>direction</strong>, making it easy to follow the conversation flow:</p><table tabindex="0"><thead><tr><th>Direction</th><th>Symbol</th><th>Description</th></tr></thead><tbody><tr><td><strong>Client to Server</strong></td><td><code>--&gt;</code></td><td>Messages sent from the client to the server</td></tr><tr><td><strong>Server to Client</strong></td><td><code>&lt;--</code></td><td>Messages sent from the server to the client</td></tr></tbody></table><p>The frame list uses visual indicators (arrows or color coding) to distinguish direction at a glance, so you can quickly trace the sequence of a bidirectional conversation.</p><details class="details custom-block"><summary>Example: Chat Application Flow</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[10:30:00.123]  --&gt;  {&quot;type&quot;: &quot;join&quot;, &quot;room&quot;: &quot;general&quot;}</span></span>
<span class="line"><span>[10:30:00.456]  &lt;--  {&quot;type&quot;: &quot;joined&quot;, &quot;room&quot;: &quot;general&quot;, &quot;users&quot;: 12}</span></span>
<span class="line"><span>[10:30:05.789]  --&gt;  {&quot;type&quot;: &quot;message&quot;, &quot;text&quot;: &quot;Hello everyone!&quot;}</span></span>
<span class="line"><span>[10:30:05.891]  &lt;--  {&quot;type&quot;: &quot;message&quot;, &quot;from&quot;: &quot;user42&quot;, &quot;text&quot;: &quot;Hello everyone!&quot;}</span></span>
<span class="line"><span>[10:30:10.234]  &lt;--  {&quot;type&quot;: &quot;message&quot;, &quot;from&quot;: &quot;user7&quot;, &quot;text&quot;: &quot;Welcome!&quot;}</span></span>
<span class="line"><span>[10:30:15.000]  --&gt;  PING</span></span>
<span class="line"><span>[10:30:15.023]  &lt;--  PONG</span></span></code></pre></div></details><h2 id="opcode-information" tabindex="-1">Opcode Information <a class="header-anchor" href="#opcode-information" aria-label="Permalink to &quot;Opcode Information&quot;">​</a></h2><p>Each WebSocket frame includes an <strong>opcode</strong> that identifies the frame type. NectoProxy displays this information for every captured frame:</p><table tabindex="0"><thead><tr><th>Opcode</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>0x0</code></td><td>Continuation</td><td>Part of a fragmented message</td></tr><tr><td><code>0x1</code></td><td>Text</td><td>UTF-8 text data</td></tr><tr><td><code>0x2</code></td><td>Binary</td><td>Binary data</td></tr><tr><td><code>0x8</code></td><td>Close</td><td>Connection close request</td></tr><tr><td><code>0x9</code></td><td>Ping</td><td>Keep-alive ping</td></tr><tr><td><code>0xA</code></td><td>Pong</td><td>Keep-alive pong</td></tr></tbody></table><p>Opcodes <code>0x3</code> through <code>0x7</code> are reserved for future non-control frames, and <code>0xB</code> through <code>0xF</code> are reserved for future control frames.</p><h2 id="binary-data-display" tabindex="-1">Binary Data Display <a class="header-anchor" href="#binary-data-display" aria-label="Permalink to &quot;Binary Data Display&quot;">​</a></h2><p>When a WebSocket connection exchanges binary data, NectoProxy provides multiple views:</p><ul><li><strong>Hex view</strong> -- Traditional hexadecimal dump with ASCII sidebar</li><li><strong>Raw size</strong> -- The byte count of the binary payload</li><li><strong>Content detection</strong> -- When possible, NectoProxy identifies the binary format (e.g., PNG, Protocol Buffers, MessagePack)</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For applications using Protocol Buffers, MessagePack, or other binary serialization formats over WebSocket, the hex view helps verify that the correct data is being transmitted even when you cannot parse the format directly.</p></div><h2 id="real-time-frame-streaming" tabindex="-1">Real-Time Frame Streaming <a class="header-anchor" href="#real-time-frame-streaming" aria-label="Permalink to &quot;Real-Time Frame Streaming&quot;">​</a></h2><p>WebSocket frames are displayed in the NectoProxy UI <strong>in real time</strong> as they are exchanged. There is no buffering or delay -- each frame appears in the frame list immediately after it is intercepted. This is essential for debugging real-time features like:</p><ul><li>Live chat and messaging</li><li>Real-time notifications</li><li>Collaborative editing</li><li>Live sports scores or financial tickers</li><li>IoT sensor data streams</li><li>Multiplayer game state synchronization</li></ul><p>The frame list auto-scrolls to keep the most recent frame visible, with an option to pause auto-scrolling when you want to examine earlier frames.</p><h2 id="filtering-websocket-traffic" tabindex="-1">Filtering WebSocket Traffic <a class="header-anchor" href="#filtering-websocket-traffic" aria-label="Permalink to &quot;Filtering WebSocket Traffic&quot;">​</a></h2><h3 id="in-the-traffic-list" tabindex="-1">In the Traffic List <a class="header-anchor" href="#in-the-traffic-list" aria-label="Permalink to &quot;In the Traffic List&quot;">​</a></h3><p>Filter the main traffic list to show only WebSocket connections by using the content type filter or searching for <code>101</code> status code (Switching Protocols).</p><h3 id="within-a-websocket-connection" tabindex="-1">Within a WebSocket Connection <a class="header-anchor" href="#within-a-websocket-connection" aria-label="Permalink to &quot;Within a WebSocket Connection&quot;">​</a></h3><p>Once you open a WebSocket connection&#39;s detail panel, you can filter the frame list by:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Description</th></tr></thead><tbody><tr><td><strong>Direction</strong></td><td>Show only client-to-server or server-to-client frames</td></tr><tr><td><strong>Frame type</strong></td><td>Show only text, binary, or control frames</td></tr><tr><td><strong>Content search</strong></td><td>Search for specific text within frame payloads</td></tr></tbody></table><h2 id="practical-examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#practical-examples" aria-label="Permalink to &quot;Practical Examples&quot;">​</a></h2><h3 id="debugging-a-real-time-chat-application" tabindex="-1">Debugging a Real-Time Chat Application <a class="header-anchor" href="#debugging-a-real-time-chat-application" aria-label="Permalink to &quot;Debugging a Real-Time Chat Application&quot;">​</a></h3><ol><li>Open your chat application and configure it to use NectoProxy</li><li>Join a chat room and send a few messages</li><li>In NectoProxy, find the WebSocket connection in the traffic list (look for the <code>101</code> response or the WS badge)</li><li>Click to open the frame list</li><li>Observe the sequence of messages: join events, message broadcasts, presence updates</li><li>Use direction filtering to see only outgoing messages (client-to-server) to verify your client is sending the correct payloads</li></ol><h3 id="monitoring-graphql-subscriptions" tabindex="-1">Monitoring GraphQL Subscriptions <a class="header-anchor" href="#monitoring-graphql-subscriptions" aria-label="Permalink to &quot;Monitoring GraphQL Subscriptions&quot;">​</a></h3><p>Many GraphQL implementations use WebSocket for subscriptions:</p><ol><li>Start a GraphQL subscription in your application</li><li>Locate the WebSocket connection in NectoProxy</li><li>Observe the subscription initialization frames</li><li>Trigger events that should produce subscription updates</li><li>Verify that the server sends the expected data in real time</li></ol><h3 id="diagnosing-connection-drop-issues" tabindex="-1">Diagnosing Connection Drop Issues <a class="header-anchor" href="#diagnosing-connection-drop-issues" aria-label="Permalink to &quot;Diagnosing Connection Drop Issues&quot;">​</a></h3><p>If a WebSocket connection is dropping unexpectedly:</p><ol><li>Capture the full lifecycle of the connection in NectoProxy</li><li>Look for close frames -- check the close code and reason</li><li>Monitor ping/pong frames to verify the keep-alive mechanism is functioning</li><li>Check for abnormal closure (code 1006) which indicates the connection was lost without a close handshake</li></ol><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>WebSocket interception requires MITM for WSS connections, which means the NectoProxy root CA certificate must be installed on the client. For WS (unencrypted) connections, no certificate installation is necessary.</p></div>`,58)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
